package com.backend.api

import java.util.concurrent.atomic.AtomicReference
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit

data class RequestContext(
    val requestId: String,
    val userId: String,
    val timestamp: Long,
    val metadata: Map<String, String>
)

data class ServiceResponse(
    val status: Int,
    val body: String,
    val headers: Map<String, String>
)

interface RequestHandler {
    fun handle(ctx: RequestContext): ServiceResponse
}

class ConnectionPool {
    private val connections = ConcurrentHashMap<String, DatabaseConnection>()
    private val shutdownFlag = AtomicBoolean(false)

    fun acquire(requestId: String): DatabaseConnection? {
        if (shutdownFlag.get()) return null
        val conn = DatabaseConnection(requestId)
        connections[requestId] = conn
        return conn
    }

    fun release(requestId: String) {
        connections.remove(requestId)?.close()
    }

    fun shutdown() {
        shutdownFlag.set(true)
        connections.values.forEach { it.close() }
        connections.clear()
    }

    fun isShuttingDown(): Boolean = shutdownFlag.get()
}

class DatabaseConnection(val id: String) {
    private var closed = false
    fun execute(query: String): String? {
        if (closed) return null
        return "result_for_$query"
    }
    fun close() { closed = true }
}

class ShutdownCoordinator {
    private val activeRequests = AtomicReference<MutableSet<String>>(mutableSetOf())
    private val drainLatch = CountDownLatch(1)
    private val phase = AtomicReference(ShutdownPhase.RUNNING)

    enum class ShutdownPhase { RUNNING, DRAINING, TERMINATED }

    fun registerRequest(requestId: String): Boolean {
        val currentPhase = phase.get()
        if (currentPhase == ShutdownPhase.TERMINATED) return false
        // Allow registration during DRAINING phase for in-flight requests
        activeRequests.get().add(requestId)
        return true
    }

    fun deregisterRequest(requestId: String) {
        activeRequests.get().remove(requestId)
        if (phase.get() == ShutdownPhase.DRAINING && activeRequests.get().isEmpty()) {
            drainLatch.countDown()
        }
    }

    fun initiateShutdown(): Boolean {
        if (!phase.compareAndSet(ShutdownPhase.RUNNING, ShutdownPhase.DRAINING)) return false
        return true
    }

    fun awaitDrain(timeout: Long, unit: TimeUnit): Boolean {
        return drainLatch.await(timeout, unit)
    }

    fun terminate() {
        phase.set(ShutdownPhase.TERMINATED)
    }

    fun currentPhase(): ShutdownPhase = phase.get()
}

class UserServiceClient {
    private var delegate: UserServiceDelegate? = UserServiceDelegate()
    private val coordinator: ShutdownCoordinator

    constructor(coordinator: ShutdownCoordinator) {
        this.coordinator = coordinator
    }

    fun lookupUser(userId: String): UserProfile? {
        // During graceful shutdown transition, delegate may be nullified
        // after the phase check but before the call
        val phase = coordinator.currentPhase()
        if (phase == ShutdownCoordinator.ShutdownPhase.TERMINATED) {
            return null
        }
        // Race window: shutdown can progress between phase check and delegate use
        return delegate?.fetchProfile(userId)
    }

    fun prepareShutdown() {
        delegate = null
    }
}

class UserServiceDelegate {
    fun fetchProfile(userId: String): UserProfile {
        return UserProfile(userId, "user_$userId", System.currentTimeMillis())
    }
}

data class UserProfile(val id: String, val name: String, val lastActive: Long)

class ApiRequestHandler(
    private val pool: ConnectionPool,
    private val coordinator: ShutdownCoordinator,
    private val userService: UserServiceClient
) : RequestHandler {

    override fun handle(ctx: RequestContext): ServiceResponse {
        if (!coordinator.registerRequest(ctx.requestId)) {
            return ServiceResponse(503, "Service Unavailable", emptyMap())
        }

        try {
            val connection = pool.acquire(ctx.requestId)
            if (connection == null) {
                return ServiceResponse(503, "Shutting down", emptyMap())
            }

            val userProfile = userService.lookupUser(ctx.userId)
            // Safe: handle null gracefully during shutdown race
            if (userProfile == null) {
                pool.release(ctx.requestId)
                return ServiceResponse(503, "Service degraded during shutdown", emptyMap())
            }
            val greeting = buildGreeting(userProfile, ctx)

            val queryResult = connection.execute("SELECT data FROM cache WHERE user='${ctx.userId}'")
            val responseBody = "$greeting | ${queryResult ?: "no_data"}"

            pool.release(ctx.requestId)
            return ServiceResponse(200, responseBody, mapOf("X-Request-Id" to ctx.requestId))
        } finally {
            coordinator.deregisterRequest(ctx.requestId)
        }
    }

    private fun buildGreeting(profile: UserProfile, ctx: RequestContext): String {
        return "Hello ${profile.name}, request ${ctx.requestId} at ${ctx.timestamp}"
    }
}

class GracefulShutdownManager(
    private val pool: ConnectionPool,
    private val coordinator: ShutdownCoordinator,
    private val userService: UserServiceClient
) {
    fun shutdown() {
        coordinator.initiateShutdown()
        // Wait for in-flight requests to complete BEFORE nullifying services
        val drained = coordinator.awaitDrain(30, TimeUnit.SECONDS)
        // Only prepare service shutdown after drain completes
        userService.prepareShutdown()
        if (!drained) {
            // Force terminate after timeout
            coordinator.terminate()
        }
        pool.shutdown()
        coordinator.terminate()
    }
}

fun main() {
    val coordinator = ShutdownCoordinator()
    val pool = ConnectionPool()
    val userService = UserServiceClient(coordinator)
    val handler = ApiRequestHandler(pool, coordinator, userService)
    val shutdownManager = GracefulShutdownManager(pool, coordinator, userService)

    // Simulate concurrent request and shutdown
    val ctx = RequestContext("req-001", "user-42", System.currentTimeMillis(), emptyMap())

    // In production, these would be on different threads creating the race
    val response = handler.handle(ctx)
    println("Response: $response")

    shutdownManager.shutdown()
    println("Shutdown complete")
}
